package com.portfolio.financeflow.model;import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.LocalDate;@Entity @Table(name="transactions")public class Transaction{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@NotBlank String type;@NotBlank String category;@Positive double amount;@NotNull LocalDate date;String note;public Long getId(){return id;}public String getType(){return type;}public void setType(String v){type=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public double getAmount(){return amount;}public void setAmount(double v){amount=v;}public LocalDate getDate(){return date;}public void setDate(LocalDate v){date=v;}public String getNote(){return note;}public void setNote(String v){note=v;}}
